"""Spell checks for wizard-arena.html. Run: python3 tests/spells_test.py  (needs Playwright). Numbers come from the Wizard 2018 rules and Spell Table."""
from playwright.sync_api import sync_playwright
JS=r'''
()=>{
 const R=[]; const ok=(n,c,extra)=>R.push([n,!!c,extra===undefined?"":String(extra)]);
 const A=P.find(h=>nbr(h,2)&&nbr(h,2).e===0&&nbr(nbr(h,2),2)); // a hex with open space around
 const mkF=o=>fromBuilder(Object.assign({name:"x",race:"human",cls:"fighter",st:12,dx:12,iq:8,a:"none",b:"none",s1:"none",d1:"dagger",armor:"none"},o));
 const unit=(p,h,f)=>{const u=mk(h,p);u.f=f;return u;};
 /* put two figures face to face: a at A, b one hex to its direction 2 */
 const B=nbr(A,2);
 const face=(a,b)=>{a.f=faceToward(a,b);b.f=faceToward(b,a);};
 let saved=rollN; const dice=(...q)=>{rollN=n=>{ if(!q.length) throw new Error("dice queue empty"); return q.shift(); };};
 const fresh=(a,b)=>{G={me:a,foe:b,log:[],floor:[],objs:[],phase:"x",turn:1,settled:true}; WALLS=new Set(); me={name:"Me",rec:null,st:a.p.st,dx:a.p.dx}; foe=b.p; };

 const ALL=["Staff","Magic Fist","Blur","Drop Weapon","Slow Movement","Clumsiness","Aid","Trip","Sleep","Fireball","Freeze","Stone Flesh","Stop","Lightning","Iron Flesh","Speed Movement","Dazzle","Blast","Break Weapon","Remove Thrown Spell","Spell Shield","Death Spell","Reverse Missiles","Flight","Teleport","Fire","Shadow","Create Wall","Rope","Destroy Creation","Summon Wolf","Summon Myrmidon","Summon Bear","Summon Gargoyle","Summon Giant","Image","Illusion","Dispel Illusions","Confusion","Shock Shield","Avert","Control Person","Control Animal","Invisibility","Mage Sight","Slippery Floor","Giant Rope","Reveal Magic"];
 const wz=(o)=>mkF(Object.assign({name:"Wiz",cls:"wizard",st:14,dx:13,iq:14,spells:ALL.filter(x=>x!=="Staff"),silver:true},o));
 const pair=(wo,fo,rear)=>{ const w=unit(wz(wo||{}),A,0), f=unit(mkF(Object.assign({name:"Foe",st:12,dx:12,a:"shortsw"},fo||{})),B,0); fresh(w,f); face(w,f); return [w,f]; };
 const cast=(w,f,sp,n)=>{ w.act={t:"cast",sp,n}; doCast(w,f,w.act); };
 ok("S1 Magic Fist with 2 ST: 2 dice minus 2 each, caster pays 2 ST",(()=>{ const [w,f]=pair(); dice([3,3,2],[5,4]); cast(w,f,"Magic Fist",2); return f.hp===12-5&&w.hp===12; })());
 ok("S2 Fireball with 1 ST: 1d-1 but never less than the ST spent",(()=>{ const [w,f]=pair(); dice([3,3,2],[1]); cast(w,f,"Fireball",1); return f.hp===11&&w.hp===13; })());
 ok("S3 Lightning has no subtraction",(()=>{ const [w,f]=pair(); dice([3,3,2],[6,6]); cast(w,f,"Lightning",2); return f.hp===0; })());
 ok("S4 armor stops damage from a missile spell",(()=>{ const [w,f]=pair({},{armor:"chain"}); dice([3,3,2],[6,6,6]); cast(w,f,"Lightning",3); return f.hp===12-15; })());
 ok("S5 a missed thrown spell costs only 1 ST",(()=>{ const [w,f]=pair(); dice([5,6,5]); cast(w,f,"Trip"); return w.hp===13&&!f.down; })());
 ok("S6 a missed missile spell costs everything put into it",(()=>{ const [w,f]=pair(); dice([5,6,5]); cast(w,f,"Fireball",3); return w.hp===11&&f.hp===12; })());
 ok("S7 a roll of 17 fizzles and costs the full price; 18 also knocks the wizard down",(()=>{ const [w,f]=pair(); dice([6,6,5]); cast(w,f,"Trip"); const a=w.hp===12&&!w.down; const [w2,f2]=pair(); dice([6,6,6]); cast(w2,f2,"Sleep"); return a&&w2.hp===11&&w2.down; })());
 ok("S8 a roll of 3 is triple and 4 double (Slow Movement lasts 4 turns x multiplier)",(()=>{ const [w,f]=pair(); dice([1,1,1]); cast(w,f,"Slow Movement"); const a=f.slow===12; const [w2,f2]=pair(); dice([1,1,2]); cast(w2,f2,"Slow Movement"); return a&&f2.slow===8; })());
 ok("S9 thrown spell range: -1 DX per hex (adjacent -1), none on self",(()=>{ const [w,f]=pair(); const a=castList(w,f).find(x=>x.sp==="Trip").dx, b=castList(w,f).find(x=>x.sp==="Blur").dx; return a===12&&b===13; })());
 ok("S10 Blur makes every attack against the subject -4 DX",(()=>{ const [w,f]=pair(); const before=adjDXu(f,"single",w); dice([3,3,2]); cast(w,f,"Blur"); return w.blur&&adjDXu(f,"single",w)===before-4; })());
 ok("S11 Stone Flesh stops 4 hits, Iron Flesh 6, on top of armor",(()=>{ const [w,f]=pair({armor:"none"}); w.stone=true; const a=stopsFor(w,f,"shortsw"); w.iron=true; return a===4&&stopsFor(w,f,"shortsw")===6; })());
 ok("S12 Clumsiness: -2 DX per ST for 3 turns",(()=>{ const [w,f]=pair(); const b0=adjDXu(f,"single",null); dice([3,3,2]); cast(w,f,"Clumsiness",2); return adjDXu(f,"single",null)===b0-4&&f.clum===3; })());
 ok("S13 Aid on yourself: +1 DX per ST for 2 turns",(()=>{ const [w,f]=pair(); const b0=adjDXu(w,"single",null); dice([3,3,2]); cast(w,f,"Aid",3); return adjDXu(w,"single",null)===b0+3&&w.aid===2; })());
 ok("S14 Trip knocks the target down; Sleep puts it down and asleep; hits wake it",(()=>{ const [w,f]=pair(); dice([3,3,2]); cast(w,f,"Trip"); const a=f.down; const [w2,f2]=pair(); dice([3,3,2]); cast(w2,f2,"Sleep"); const b=f2.sleep&&f2.down; dice([3,3,2],[6]); cast(w2,f2,"Magic Fist",1); return a&&b&&f2.sleep===false; })());
 ok("S15 Sleep does not work on ST 20 or more (not offered)",(()=>{ const [w,f]=pair({},{st:20,dx:12,a:"twohsw"}); return !castList(w,f).some(x=>x.sp==="Sleep"); })());
 ok("S16 Freeze rolls 2 dice for the number of turns; frozen figures cannot act",(()=>{ const [w,f]=pair(); dice([3,3,2],[4,3]); cast(w,f,"Freeze"); return f.frozen===7&&options(f,w).length===0; })());
 ok("S17 Drop Weapon puts the weapon on the floor",(()=>{ const [w,f]=pair(); dice([3,3,2]); cast(w,f,"Drop Weapon"); return f.right==="none"&&G.floor.some(x=>x.id==="shortsw"); })());
 ok("S18 Slow halves MA, Stop sets it to 0; both count down each turn",(()=>{ const [w,f]=pair(); f.slow=2; f.stop=0; const a=MAu(f)===5; f.stop=1; const b=MAu(f)===0; f.slow=4; return a&&b; })());
 ok("S19 a wizard cannot cast a spell that would take ST below 0, but may take it to 0",(()=>{ const [w,f]=pair(); w.hp=2; const L=castList(w,f); return L.every(x=>x.cost<=2)&&L.some(x=>x.cost===2); })());
 ok("S20 iron or steel armor or weapon instead of silver: extra -4 to casting only",(()=>{ const [w,f]=pair({silver:false,armor:"chain"}); const sv=pair({silver:true,armor:"chain"})[0]; return ironU(w)&&castBase(w)===castBase(sv)-4; })());
 ok("S21 the missile spell range uses megahexes and needs the target in front",(()=>{ const [w,f]=pair(); const ok1=castList(w,f).some(x=>x.sp==="Magic Fist"); w.f=(faceToward(w,f)+3)%6; return ok1&&!castList(w,f).some(x=>x.sp==="Magic Fist"); })());
 ok("S22 a Magic Fist doing 6 or more hits can trip its target",(()=>{ const [w,f]=pair({},{st:20}); dice([3,3,2],[6,6,6],[6,6,6]); cast(w,f,"Magic Fist",3); return f.down===true&&f.hp===8; })());
 ok("S23 spell upkeep: a continuing spell is kept for 1 ST or dropped",(()=>{ const [w,f]=pair(); w.blur=true; G.me=w; G.foe=f; const before=w.hp; G.rlist=[{k:"blur",on:true}]; G.afterRenew=()=>{}; doRenew(); return w.blur&&w.hp===before-1; })());
 ok("S24 the computer wizard opponent knows spells, carries a staff and casts something sensible",(()=>{ me=fromBuilder({name:"Me",race:"human",cls:"fighter",st:12,dx:12,iq:8,a:"shortsw",armor:"leather",d1:"dagger"}); const f=makeWizard(); return f.cls==="wizard"&&f.right==="staff"&&f.spells.length>5&&f.iq>=11; })());

 ok("S25 Speed Movement doubles MA for 4 turns; with Slow Movement they cancel",(()=>{ const [w,f]=pair(); const m0=MAu(w); dice([3,3,2]); cast(w,f,"Speed Movement"); const a=MAu(w)===2*m0&&w.spd===4&&w.hp===12; w.slow=2; return a&&MAu(w)===m0; })());
 ok("S26 Dazzle: -3 DX for 3 turns, 3 ST, not stacked with Blur's -4",(()=>{ const [w,f]=pair(); const b0=adjDXu(f,"single",null); dice([3,3,2]); cast(w,f,"Dazzle"); const a=f.daz===3&&adjDXu(f,"single",null)===b0-3&&w.hp===11; w.blur=true; return a&&adjDXu(f,"single",w)===b0-4; })());
 ok("S27 Blast: 1 die to everyone adjacent, armor stops it, 2 ST",(()=>{ const [w,f]=pair({},{armor:"none"}); dice([3,3,2],[5]); cast(w,f,"Blast"); const a=f.hp===7&&w.hp===12; const [w2,f2]=pair({},{armor:"leather"}); dice([3,3,2],[5]); cast(w2,f2,"Blast"); return a&&f2.hp===12-3; })());
 ok("S28 Blast and Dazzle are special spells: a miss loses just 1 ST; Dazzle reaches 5 megahexes",(()=>{ const [w,f]=pair(); dice([5,6,5]); cast(w,f,"Blast"); const a=w.hp===13&&f.hp===12; const [w2,f2]=pair(); const d=castList(w2,f2).find(x=>x.sp==="Dazzle"); return a&&!!d&&d.dx===castBase(w2); })());
 ok("S29 Break Weapon halves a weapon's damage; staves and shields are destroyed",(()=>{ const [w,f]=pair({},{a:"broad",st:14}); dice([3,3,2]); cast(w,f,"Break Weapon"); const a=f.brkW==="broad" ; const [w2,f2]=pair({},{a:"shortsw",b:"smallsh"}); dice([3,3,2]); cast(w2,f2,"Break Weapon"); return !!a&&f2.brkW==="shortsw"; })());
 ok("S30 a broken weapon: the rolled total is halved, rounded down",(()=>{ const [w,f]=pair({},{a:"shortsw"}); f.brkW="shortsw"; dice([3,2]); const r=dmgRoll(f,"shortsw"); return r.total===Math.floor((5+W.shortsw.m)/2); })());
 ok("S31 Remove Thrown Spell ends the target's thrown spells",(()=>{ const [w,f]=pair(); f.blur=true; f.stone=true; f.slow=3; dice([3,3,2]); cast(w,f,"Remove Thrown Spell"); return !f.blur&&!f.stone&&f.slow===0&&w.hp===12; })());
 ok("S32 Spell Shield: spells cast at the subject do nothing and the caster loses the full cost",(()=>{ const [w,f]=pair(); f.shield=true; dice([3,3,2]); cast(w,f,"Slow Movement"); const a=f.slow===0&&w.hp===12; dice([3,3,2],[6,6]); cast(w,f,"Lightning",2); return a&&f.hp===12&&w.hp===10; })());
 ok("S33 Spell Shield costs 3 ST, +1 per turn, and also blocks the wizard's own spells",(()=>{ const [w,f]=pair(); dice([3,3,2]); cast(w,f,"Spell Shield"); const a=w.shield&&w.hp===11&&CONT.includes("shield"); return a&&!castList(w,f).some(x=>x.sp==="Blur"); })());
 ok("S34 Death Spell: the weaker dies, the stronger loses the weaker's ST; Spell Shield costs the caster only 1",(()=>{ const [w,f]=pair({st:20},{st:8}); dice([3,3,2]); cast(w,f,"Death Spell"); const a=f.hp===-1&&w.hp===12; const [w2,f2]=pair({st:8},{st:20}); dice([3,3,2]); cast(w2,f2,"Death Spell"); const b=w2.hp===-1; const [w3,f3]=pair(); f3.shield=true; dice([3,3,2]); cast(w3,f3,"Death Spell"); return a&&b&&w3.hp===13&&f3.hp===12; })());
 ok("S35 the computer wizard can know the new spells",(()=>{ me=fromBuilder({name:"Me",race:"human",cls:"fighter",st:12,dx:12,iq:8,a:"shortsw",armor:"leather",d1:"dagger"}); let seen=false; for(let i=0;i<40&&!seen;i++){ const f=makeWizard(); if(f.spells.includes("Dazzle")) seen=true; } return seen; })());

 ok("S36 Reverse Missiles costs 2 ST, +1 a turn; a missile that hits turns back on the shooter",(()=>{ const [w,f]=pair({},{a:"lbow",st:12}); dice([3,3,2]); cast(w,f,"Reverse Missiles"); const a=w.rev&&w.hp===12&&CONT.includes("rev"); const h=f.hp, wh=w.hp; dice([1,1,6],[3,3]); doAttack(f,w,"lbow","single","missile"); return a&&w.hp===wh&&f.hp<h; })());
 ok("S37 Reverse Missiles turns a Magic Fist back on its caster; both protected means no harm",(()=>{ const [w,f]=pair({},{}); const f2=mkF({name:"W2",cls:"wizard",st:14,dx:13,iq:14,spells:["Magic Fist"],silver:true}); const e=unit(f2,B,0); const w1=unit(wz({}),A,0); fresh(w1,e); face(w1,e); e.rev=true; dice([3,3,2],[5,4]); cast(w1,e,"Magic Fist",2); const a=e.hp===14&&w1.hp<12; w1.rev=true; const h=w1.hp; dice([3,3,2]); cast(w1,e,"Magic Fist",1); return a&&e.hp===14&&w1.hp===h-1; })());
 ok("S38 Reverse Missiles does nothing against melee blows",(()=>{ const [w,f]=pair({},{a:"shortsw"}); w.rev=true; const h=f.hp; dice([1,1,6],[3,3]); doAttack(f,w,"shortsw","single",null); return f.hp===h&&w.hp<14; })());

 ok("S39 Flight: 3 ST, +1 a turn; in the air from next turn, half MA (6) first turn then 12; not engaged by a ground figure",(()=>{ const [w,f]=pair(); dice([3,3,2]); cast(w,f,"Flight"); const a=w.fly&&!w.air&&w.hp===11&&CONT.includes("fly"); w.air=true; w.airN=1; const b=MAu(w)===6; w.airN=2; return a&&b&&MAu(w)===12&&!isEngaged(w,f)&&!isEngaged(f,w); })());
 ok("S40 attacks on a flier are -4 DX; a flier attacks at -2 (-4 with missile weapons); spells at a flier -4, spells it casts -2",(()=>{ const [w,f]=pair(); const b0=adjDXu(f,"single",w), c0=adjDXu(w,"single",f), s0=castList(w,f).find(x=>x.sp==="Trip").dx; w.air=true; return adjDXu(f,"single",w)===b0-4&&adjDXu(w,"single",f)===c0-2&&castList(f.p.cls==="wizard"?f:w,f)!==null&&castList(w,f).find(x=>x.sp==="Trip").dx===s0-2&&shotDX(w,f,"lbow","missile")===shotDX(f,w,"lbow","missile")-4+0-0-0+(adjDXu(w,"single",null)-adjDXu(f,"single",null))+4; })());
 ok("S41 a flier cannot be tripped, cannot be grappled, and lands (no ground move that turn) when Flight lapses or is removed",(()=>{ const [w,f]=pair(); f.air=true; f.fly=true; dice([3,3,2]); cast(w,f,"Trip"); const a=!f.down; const b=!canHth(w,f); dice([3,3,2]); cast(w,f,"Remove Thrown Spell"); return a&&b&&!f.air&&!f.fly&&MAu(f)===0; })());

 ok("S42 Teleport: 1 ST per megahex moved, you arrive facing the enemy; a miss costs 1 ST",(()=>{ const [w,f]=pair(); const far=P.filter(h=>!same(h,f)&&mhDist(A,h)===3)[0]; dice([3,3,2]); w.act={t:"cast",sp:"Teleport",dest:far}; doCast(w,f,w.act); const a=w.q===far.q&&w.r===far.r&&w.hp===14-3&&w.f===faceToward(w,f); const [w2,f2]=pair(); dice([5,6,5]); w2.act={t:"cast",sp:"Teleport",dest:far}; doCast(w2,f2,w2.act); return a&&w2.q===A.q&&w2.hp===13; })());
 ok("S43 Teleport cannot go into the enemy's hex or cost more ST than you have",(()=>{ const [w,f]=pair(); doCast(w,f,{t:"cast",sp:"Teleport",dest:{q:f.q,r:f.r}}); const a=w.q===A.q; w.hp=2; const far=P.filter(h=>!same(h,f)&&mhDist(A,h)>=4)[0]; doCast(w,f,{t:"cast",sp:"Teleport",dest:far}); return a&&w.q===A.q&&w.hp===2; })());

 const mkObj=(ty,h)=>{ G.objs.push({t:ty,q:h.q,r:h.r,age:0}); syncWalls(); };
 ok("S44 Fire: 1 ST, appears in your megahex or next to it; a figure in the hex takes 2 hits (armor stops them)",(()=>{ const [w,f]=pair({},{armor:"none"}); const hx=creaHexes(w,f,"fire"); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Fire",dest:{q:f.q,r:f.r}}); const a=hx.length>3&&G.objs.length===1&&w.hp===13&&f.hp===10; const [w2,f2]=pair({},{armor:"leather"}); dice([3,3,2]); doCast(w2,f2,{t:"cast",sp:"Fire",dest:{q:f2.q,r:f2.r}}); const far=P.find(h=>mhDist(w2,h)>=3); doCast(w2,f2,{t:"cast",sp:"Fire",dest:far}); return a&&f2.hp===12&&G.objs.length===1; })());
 ok("S45 Create Wall: 2 ST, blocks movement and the line of fire, never over a figure",(()=>{ const [w,f]=pair(); const C=nbr(f,2); if(!C) return true; doCast(w,f,{t:"cast",sp:"Create Wall",dest:{q:f.q,r:f.r}}); const a=G.objs.length===0; dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Create Wall",dest:{q:f.q+DIRS[2][0],r:f.r+DIRS[2][1]}}); const far=P.find(h=>dist(h,f)===2&&dist(h,w)===3&&mhDist(w,h)<=1); return a&&G.objs.length===1&&w.hp===12; })());
 ok("S46 a wall blocks missiles and spells that pass through its hex, and nobody can walk into it",(()=>{ const [w,f]=pair(); const F2=nbr(f,2); if(!F2||!nbr(F2,2)) return true; const f3=unit(mkF({name:"Far",a:"shortsw"}),F2,0); const mid=f; mkObj("wall",{q:A.q+(F2.q-A.q)/2|0,r:0}); G.objs.length=0; syncWalls(); mkObj("wall",f); const line=lineHexes(w,{q:f.q+DIRS[2][0],r:f.r+DIRS[2][1]}); return blocked(w,{q:f.q+DIRS[2][0],r:f.r+DIRS[2][1]})&&!nbr(w,2)&&line.length===1; })());
 ok("S47 Shadow: attacks into it are -4 DX, attacks from it -6, and a missile or spell likewise",(()=>{ const [w,f]=pair(); const b0=adjDXu(w,"single",f); mkObj("shadow",f); const a=adjDXu(w,"single",f)===b0-4; G.objs.length=0; mkObj("shadow",w); return a&&adjDXu(w,"single",f)===b0-6; })());
 ok("S48 Rope: 2 ST, MA halved, DX -2 and one worse each turn, not on ST 20 or more; standing still lets you roll to break free",(()=>{ const [w,f]=pair(); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Rope"}); const m0=MA(f.p), b=adjDXu(f,"single",null); const a=f.rope===1&&MAu(f)===Math.floor(m0/2); const d0=adjDXu(f,"single",null); f.rope=2; const c=adjDXu(f,"single",null)===d0-1; dice([2,2,2]); doUnrope(f); const [w2,f2]=pair({},{st:20,a:"twohsw"}); return a&&c&&f.rope===0&&!castList(w2,f2).some(x=>x.sp==="Rope"); })());
 ok("S49 Destroy Creation removes one created thing for 1 ST",(()=>{ const [w,f]=pair(); mkObj("wall",P.find(h=>dist(h,w)===3&&mhDist(w,h)<=1&&!same(h,f))); const L=castList(w,f).filter(x=>x.sp==="Destroy Creation"); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Destroy Creation",objId:0}); return L.length===1&&G.objs.length===0&&WALLS.size===0&&w.hp===13; })());
 ok("S50 moving through fire: 2 hits per hex passed, 4 and -2 DX if you stop in it; armor comes off the total",(()=>{ const [w,f]=pair({},{armor:"leather"}); mkObj("fire",{q:0,r:0}); const u=f; u.q=0;u.r=0; fireMove(u,{fire:3}); return u.hp===12-(8-2)&&u.fireT===true; })());

 ok("S51 Summon Wolf: 2 ST, a Wolf (ST 10, DX 14, MA 12, bite 1d+1, fur stops 1) appears in a free hex nearby and cannot act that turn",(()=>{ const [w,f]=pair(); const hx=creaHexes(w,f,"summon"); const h=hx[0]; dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Summon Wolf",dest:h}); const m=allU().find(x=>x.minion); return !!m&&w.hp===12&&m.p.st===10&&m.p.dx===14&&MA(m.p)===12&&m.right==="bite"&&stopsFor(m,f,"shortsw")===1&&m.fresh&&sideOf(m)==="me"&&aiAct(m,f).t==="none"&&same(m,h); })());
 ok("S52 a summoned figure is on its owner's side: enemies see it, it blocks hexes, targets are the nearest enemy",(()=>{ const [w,f]=pair(); const h=creaHexes(w,f,"summon").find(x=>dist(x,f)===1&&!same(x,w)); if(!h) return true; dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Summon Wolf",dest:h}); const m=allU().find(x=>x.minion); return enemiesOf(f).includes(m)&&enemiesOf(f).includes(w)&&!enemiesOf(m).includes(w)&&other(m)===f&&!freeNeighbors(w).some(x=>same(x,m)); })());
 ok("S53 a minion cannot grapple, and a summoned Bear or Giant is the strength the rules give",(()=>{ const [w,f]=pair(); const m=summonMinion(w,"bear",creaHexes(w,f,"summon")[0]); const g=summonMinion(w,"giant",creaHexes(w,f,"summon")[1]); return !canHth(m,f)&&m.p.st===30&&(dice([2,3]),dmgRoll(m,"bite2").total===7)&&g.p.st===30&&W.club3.d===3&&W.club3.m===3; })());
 ok("S54 a minion dies at 0 ST and is removed; upkeep: dropping it from the renew list makes it vanish",(()=>{ const [w,f]=pair(); const m=summonMinion(w,"wolf",creaHexes(w,f,"summon")[0]); G.me=w; G.foe=f; G.phase="x"; m.hp=-1; endCheck(); const a=m.gone; const m2=summonMinion(w,"wolf",creaHexes(w,f,"summon")[0]); G.rlist=[{k:"minion",m:m2,on:false}]; G.afterRenew=()=>{}; doRenew(); return a&&m2.hp===0&&m2.gone; })());
 ok("S55 a computer wizard with a summon spell can bring one (with a hex chosen)",(()=>{ const wz2=mkF({name:"W2",cls:"wizard",st:16,dx:13,iq:14,spells:["Summon Bear","Summon Wolf"],silver:true}); const e=unit(wz2,B,0); const w1=unit(mkF({name:"P",a:"shortsw"}),A,0); fresh(w1,e); face(w1,e); let got=false; for(let i=0;i<60&&!got;i++){ const c=aiCast(e,w1); if(c&&c.dest) got=true; } return got; })());

 const mkFake=(w,f,kind,form)=>{ const m=summonMinion(w,form||"wolf",creaHexes(w,f,"summon")[0]); m.fake=kind; m.fresh=false; return m; };
 ok("S56 Image costs 1 ST and Illusion 2; the log does not say which spell it was",(()=>{ const [w,f]=pair(); const L=castList(w,f); const a=L.some(x=>x.sp==="Image"&&x.cost===1&&x.form==="wolf")&&L.some(x=>x.sp==="Illusion"&&x.cost===2&&x.form==="bear"); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Illusion",form:"bear",dest:creaHexes(w,f,"summon")[0]}); const m=allU().find(x=>x.minion); return a&&m.fake==="illusion"&&m.p.name==="Bear"&&w.hp===12&&!G.log.some(l=>/Illusion|Image/.test(l)); })());
 ok("S57 an image that hits or is hit vanishes and does no damage",(()=>{ const [w,f]=pair(); const m=mkFake(w,f,"image","bear"); const h=f.hp; dice([1,1,1]); doAttack(f,m,"shortsw","single"); const a=m.hp===0&&m.gone===undefined||m.hp===0; const m2=mkFake(w,f,"image","wolf"); m2.q=f.q+DIRS[3][0]; m2.r=f.r+DIRS[3][1]; dice([1,1,1]); doAttack(m2,f,"bite","single"); return a&&m2.hp===0&&f.hp===h; })());
 ok("S58 an illusion fights and hurts like the real thing",(()=>{ const [w,f]=pair(); const m=mkFake(w,f,"illusion","bear"); const h=f.hp; dice([1,1,1],[3,3]); doAttack(m,f,"bite2","single"); return f.hp<h&&m.p.st===30; })());
 ok("S59 Disbelieve: a human-type figure can try, the owner rolls 3 dice against its IQ; an illusion vanishes, a real creature stays",(()=>{ const [w,f]=pair(); const m=mkFake(w,f,"illusion","wolf"); const real=summonMinion(w,"giant",creaHexes(w,f,"summon")[1]); const o1=options(f,m).some(x=>x.t==="disbelieve"); dice([2,2,2]); doDisbelieve(f,m); const a=m.hp===0; dice([2,2,2]); doDisbelieve(f,real); const b=real.hp>0; const m3=mkFake(w,f,"illusion","wolf"); dice([6,6,6]); doDisbelieve(f,m3); return o1&&a&&b&&m3.hp>0&&!options(m3,f).some(x=>x.t==="disbelieve"); })());
 ok("S60 Dispel Illusions: 5 ST, removes every image and illusion within 5 megahexes, not real creatures",(()=>{ const [w,f]=pair(); w.hp=14; const i1=mkFake(w,f,"image","wolf"), i2=mkFake(w,f,"illusion","bear"), r=summonMinion(w,"wolf",creaHexes(w,f,"summon")[2]); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Dispel Illusions"}); return i1.hp===0&&i2.hp===0&&r.hp>0&&w.hp===9; })());
 ok("S61 a Magic Fist or Death Spell at an image only destroys it (the Death Spell costs the caster 1 ST); an illusion is treated as alive",(()=>{ const [w,f]=pair(); const im=mkFake(w,f,"image","bear"); im.q=f.q; im.r=f.r; dice([3,3,2]); doCast(w,im,{t:"cast",sp:"Magic Fist",n:1}); const a=im.hp===0&&w.hp===13; const im2=mkFake(w,f,"image","bear"); im2.q=f.q; im2.r=f.r; const h=w.hp; dice([3,3,2]); doCast(w,im2,{t:"cast",sp:"Death Spell"}); const b=im2.hp===0&&w.hp===h-1; const il=mkFake(w,f,"illusion","wolf"); il.q=f.q; il.r=f.r; w.hp=30; dice([3,3,2]); doCast(w,il,{t:"cast",sp:"Death Spell"}); return a&&b&&il.hp===-1&&w.hp===20; })());
 ok("S62 images and illusions cost no upkeep: only real creatures appear in the renew step",(()=>{ const [w,f]=pair(); mkFake(w,f,"illusion","wolf"); mkFake(w,f,"image","bear"); const real=summonMinion(w,"wolf",creaHexes(w,f,"summon")[3]); return allU().filter(x=>x.minion&&!x.fake).length===1&&allU().filter(x=>x.minion&&x.fake).length===2&&real&&true; })());
 { const [w,f]=pair({},{cls:"wizard",iq:14,st:14,spells:["Magic Fist","Dispel Illusions"]}); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Confusion",n:2}); const l=castList(f,w).map(c=>c.sp); ok("S63 Confusion lowers IQ by 2 per ST for 3 turns and removes spells above the new IQ from the list",f.conf===3&&f.confN===4&&effIQ(f)===10&&l.includes("Magic Fist")&&!l.includes("Dispel Illusions"),JSON.stringify([f.conf,f.confN,effIQ(f),l,G.log.slice(-2)])); }
 ok("S64 Confusion wears off after its turns",(()=>{ const [w,f]=pair(); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Confusion",n:1}); nextTurn(); nextTurn(); nextTurn(); return f.conf===0&&f.confN===0&&effIQ(f)===f.p.iq; })());
 ok("S65 Shock Shield burns a figure sharing the subject's hex at end of turn, and not the subject",(()=>{ const [w,f]=pair(); dice([3,3,2]); doCast(w,w,{t:"cast",sp:"Shock Shield"}); f.q=w.q; f.r=w.r; const h=f.hp,wh=w.hp; dice([6]); applyShock(); return w.shock===true&&f.hp<h&&w.hp===wh; })());
 ok("S66 Shock Shield is a running spell on the caster",(()=>{ const [w,f]=pair(); dice([3,3,2]); doCast(w,w,{t:"cast",sp:"Shock Shield"}); return w.shock===true; })());
 ok("S67 Avert (2 ST) marks the victim; his reachable hexes are all at least 2 farther from the caster",(()=>{ const [w,f]=pair(); dice([3,3,2]); const s=w.hp; doCast(w,f,{t:"cast",sp:"Avert"}); if(f.avert!==w||s-w.hp!==2) return false; const st={q:f.q,r:f.r}, R=reach(st,[w],6,false); const d0=dist(st,w); const fall=avertFilter(f,R,st); return !fall&&R.size>0&&[...R.values()].every(h=>dist(h,w)>=d0+2); })());
 ok("S68 a cornered Avert victim keeps only the farthest hexes he can reach; with none he must roll to avoid a fall",(()=>{ const [w,f]=pair(); f.avert=w; const st={q:f.q,r:f.r}; const R=new Map([[key(st.q,st.r),{q:st.q,r:st.r,c:0}]]); const fall=avertFilter(f,R,st); return fall===true&&R.size===1; })());
 ok("S69 Avert ends when the caster drops it at renewal and Remove Thrown Spell clears it",(()=>{ const [w,f]=pair(); f.avert=w; G.rlist=[{k:"avert",m:f,on:false}]; G.afterRenew=()=>{}; G.phase="renew"; doRenew(); const a=f.avert===null; f.avert=w; f.p.spells=[]; dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Remove Thrown Spell",on:"foe"}); return a&&f.avert===null; })());
 ok("S70 the computer foe, when Averted, moves away and a caster who dies frees the victim",(()=>{ const [w,f]=pair(); f.avert=w; const d0=dist(f,w); aiMove(f); const moved=dist(f,w)>=d0; f.avert=w; w.hp=0; const R=reach({q:f.q,r:f.r},[w],6,false); return moved&&avertFilter(f,R,{q:f.q,r:f.r})===false; })());

 const enemyMin=(w,f,kind)=>{ const m=summonMinion(f,kind,{q:f.q,r:f.r}); m.fresh=false; return m; };
 ok("S71 Control Person on an enemy giant: failed save puts it on the caster's side for 3 ST",(()=>{ const [w,f]=pair(); const g=enemyMin(w,f,"giant"); const s0=w.hp; dice([3,3,2],[6,6,6]); doCast(w,g,{t:"cast",sp:"Control Person"}); return g.ctl===w&&sideOf(g)===sideOf(w)&&s0-w.hp===3; })());
 ok("S72 a successful saving roll costs the caster only 1 ST and leaves the figure alone",(()=>{ const [w,f]=pair(); const g=enemyMin(w,f,"giant"); const s0=w.hp; dice([3,3,2],[1,1,1]); doCast(w,g,{t:"cast",sp:"Control Person"}); return !g.ctl&&sideOf(g)===sideOf(f)&&s0-w.hp===1; })());
 ok("S73 Control Animal only offered against animals, Control Person only against humanoids",(()=>{ const [w,f]=pair(); const g=enemyMin(w,f,"giant"); const a=castList(w,g).map(c=>c.sp); const wf=enemyMin(w,f,"wolf"); const b=castList(w,wf).map(c=>c.sp); return a.includes("Control Person")&&!a.includes("Control Animal")&&b.includes("Control Animal")&&!b.includes("Control Person"); })());
 ok("S74 an image of a giant vanishes when a Control spell hits it",(()=>{ const [w,f]=pair(); const m=enemyMin(w,f,"giant"); m.fake="image"; dice([3,3,2]); doCast(w,m,{t:"cast",sp:"Control Person"}); return m.hp===0&&!m.ctl; })());
 ok("S75 a controlled creature appears in its new master's renew list and vanishes if not renewed",(()=>{ const [w,f]=pair(); const g=enemyMin(w,f,"giant"); g.ctl=w; const mins=allU().filter(x=>x.minion&&!x.fake&&x.hp>0&&sideOf(x)==="me"); g.hp=0; endCheck(); return mins.includes(g)&&g.gone===true; })());
 ok("S76 Control Person on the lone enemy fighter: he changes sides and then holds; releasing him restores his side",(()=>{ const [w,f]=pair(); f.p.iq=8; dice([3,3,2],[6,6,6]); doCast(w,f,{t:"cast",sp:"Control Person"}); const a=sideOf(f)===sideOf(w)&&ctlsOf(w).includes(f); const act=aiAct(f,w); releaseCtl(f); return a&&act.t==="none"&&sideOf(f)==="foe"; })());
 ok("S77 a controlled creature ordered against a foe over twice its ST may break the spell with an IQ save",(()=>{ const [w,f]=pair(); const wolf=enemyMin(w,f,"wolf"); const big=enemyMin(w,f,"giant"); big.side="foe"; wolf.ctl=w; wolf.fresh=false; dice([1,1,1]); const r=aiAct(wolf,big); return wolf.ctl===null&&wolf.hp===0&&r.t==="none"; })());

 ok("S78 Invisibility costs 3 ST on yourself and is a running spell",(()=>{ const [w,f]=pair(); const s0=w.hp; dice([3,3,2]); doCast(w,w,{t:"cast",sp:"Invisibility"}); return w.inv===true&&s0-w.hp===3&&CONT.includes("inv"); })());
 ok("S79 attacks against an invisible figure are at −6 DX, and the penalty does not add to Blur or Shadow",(()=>{ const [w,f]=pair(); const base=adjDXu(f,"single",w); w.inv=true; const a=adjDXu(f,"single",w); w.blur=true; const b=adjDXu(f,"single",w); return base-a===6&&base-b===6; })());
 ok("S80 spells at an invisible target need 6 less, and a Magic Fist is offered at the lowered number",(()=>{ const [w,f]=pair({},{cls:"wizard",st:14,iq:12,spells:["Magic Fist"]}); const a=castList(f,w).find(c=>c.sp==="Magic Fist"&&c.n===1).dx; w.inv=true; const b=castList(f,w).find(c=>c.sp==="Magic Fist"&&c.n===1).dx; return a-b===6; })());
 ok("S81 Remove Thrown Spell ends Invisibility",(()=>{ const [w,f]=pair(); f.inv=true; dice([1,1,1]); doCast(w,f,{t:"cast",sp:"Remove Thrown Spell",on:"foe"}); return f.inv===false; })());

 ok("S82 Mage Sight costs 2 ST on yourself and is a running spell",(()=>{ const [w,f]=pair(); const s0=w.hp; dice([3,3,2]); doCast(w,w,{t:"cast",sp:"Mage Sight"}); return w.sight===true&&s0-w.hp===2&&CONT.includes("sight"); })());
 ok("S83 a figure with Mage Sight attacks an invisible, blurred or shadowed target at full DX",(()=>{ const [w,f]=pair(); const base=adjDXu(f,"single",w); w.inv=true; w.blur=true; const a=adjDXu(f,"single",w); f.sight=true; const b=adjDXu(f,"single",w); return a<base&&b===base; })());
 ok("S84 a wizard with Mage Sight casts at an invisible target at the normal number",(()=>{ const [w,f]=pair({},{cls:"wizard",st:14,iq:12,spells:["Magic Fist"]}); const a=castList(f,w).find(c=>c.sp==="Magic Fist"&&c.n===1).dx; w.inv=true; const b=castList(f,w).find(c=>c.sp==="Magic Fist"&&c.n===1).dx; f.sight=true; const c2=castList(f,w).find(c=>c.sp==="Magic Fist"&&c.n===1).dx; return b===a-6&&c2===a; })());

 const slick=(w,f,at)=>{ const c=at||{q:f.q,r:f.r}; const g={shown:false}; [c].concat(P.filter(h=>dist(h,c)===1)).forEach(h=>G.objs.push({t:"slick",q:h.q,r:h.r,age:0,g,owner:w})); return g; };
 { const [w,f]=pair(); const s0=w.hp; dice([3,3,2],[3],[18]); doCast(w,f,{t:"cast",sp:"Slippery Floor",dest:{q:f.q,r:f.r}}); const n=G.objs.filter(o=>o.t==="slick").length; ok("S85 Slippery Floor costs 3 ST, makes seven hexes slick, and a figure standing in it rolls DX at once",s0-w.hp===3&&n===7&&f.down===true&&G.objs.find(o=>o.t==="slick").g.shown===true,JSON.stringify([s0-w.hp,n,f.down,G.log.slice(-3)])); }
 ok("S86 a figure that passes the DX roll stays on his feet",(()=>{ const [w,f]=pair(); dice([3,3,2],[3],[3]); doCast(w,f,{t:"cast",sp:"Slippery Floor",dest:{q:f.q,r:f.r}}); return f.down===false; })());
 ok("S87 entering a slick hex needs a saving roll; a failed roll drops the figure and reveals the floor",(()=>{ const [w,f]=pair(); const g=slick(w,f); const o2=nbr(f,0)||nbr(f,1); f.q=o2.q; f.r=o2.r; dice([18]); slipMove(f,{q:o2.q,r:o2.r,c:1,slk:1}); return f.down===true&&g.shown===true; })());
 ok("S88 standing still on a slick hex still needs a roll each turn, a fallen figure must roll DX to stand",(()=>{ const [w,f]=pair(); slick(w,f); dice([18]); slipMove(f,{q:f.q,r:f.r,c:0,slk:0}); const a=f.down; dice([18]); const stood=slickStand(f); dice([3]); const stood2=slickStand(f); return a&&stood===false&&stood2===true; })());
 ok("S89 a slick hex adds to the path count in reach, and fliers are not affected",(()=>{ const [w,f]=pair(); slick(w,f,{q:f.q,r:f.r}); const R=reach({q:w.q,r:w.r},[f],6,false); const any=[...R.values()].some(h=>h.slk>0); f.air=true; slipMove(f,{q:f.q,r:f.r,c:0,slk:0}); return any&&!f.down; })());
 ok("S90 the computer will not step into another slick hex it can see",(()=>{ const [w,f]=pair(); const g=slick(w,f); g.shown=true; const st={q:f.q,r:f.r}; dice([3],[3],[3]); aiMove(f); return !slickAt(f)||(f.q===st.q&&f.r===st.r); })());

 ok("S91 Giant Rope on a weaker creature: 5 ST, two ropes at once (MA quartered, DX -4)",(()=>{ const [w,f]=pair(); const s0=w.hp, m0=MA(f.p), b=adjDXu(f,"single",null); const L=castList(w,f).find(x=>x.sp==="Giant Rope"); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Giant Rope"}); return !!L&&L.cost===5&&s0-w.hp===5&&f.rope===1&&f.ropeN===2&&MAu(f)===Math.floor(Math.floor(m0/2)/2)&&adjDXu(f,"single",null)===b-4; })());
 ok("S92 Giant Rope on ST 20 or more works like one ordinary Rope, and plain Rope is not offered against it",(()=>{ const [w,f]=pair({},{st:20,a:"twohsw"}); const m0=MA(f.p), b=adjDXu(f,"single",null); const L=castList(w,f); const a=L.some(x=>x.sp==="Giant Rope")&&!L.some(x=>x.sp==="Rope"); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Giant Rope"}); return a&&f.rope===1&&f.ropeN===1&&MAu(f)===Math.floor(m0/2)&&adjDXu(f,"single",null)===b-2; })());
 ok("S93 two ropes each get one worse every turn (DX -6 on the second turn)",(()=>{ const [w,f]=pair(); const b=adjDXu(f,"single",null); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Giant Rope"}); f.rope=2; return adjDXu(f,"single",null)===b-6; })());
 ok("S94 struggling free takes off one rope per success; a failed roll changes nothing",(()=>{ const [w,f]=pair(); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Giant Rope"}); dice([6,6,6]); doUnrope(f); const a=f.rope===1&&f.ropeN===2; dice([2,2,2]); doUnrope(f); const b=f.rope===1&&f.ropeN===1; dice([2,2,2]); doUnrope(f); return a&&b&&f.rope===0&&f.ropeN===0; })());
 ok("S95 two ropes can leave a figure helpless at once (DX 5 in chain mail -> 1), one rope cannot (-> 3)",(()=>{ const [w,f]=pair({},{dx:8,armor:"chain"}); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Giant Rope"}); const a=f.down===true; const [w2,f2]=pair({},{dx:8,armor:"chain"}); dice([3,3,2]); doCast(w2,f2,{t:"cast",sp:"Rope"}); return a&&f2.down===false&&f2.rope===1&&f2.ropeN===1; })());
 ok("S96 a Spell Shield does not stop a rope, and a roped figure cannot be roped again",(()=>{ const [w,f]=pair(); f.shield=true; dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Giant Rope"}); const a=f.rope===1&&f.ropeN===2; return a&&!castList(w,f).some(x=>x.sp==="Giant Rope"||x.sp==="Rope"); })());
 ok("S97 a Giant Rope counts one rope fewer once one is cut: MA goes from a quarter to a half",(()=>{ const [w,f]=pair(); const m0=MA(f.p); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Giant Rope"}); const a=MAu(f); dice([2,2,2]); doUnrope(f); return a===Math.floor(Math.floor(m0/2)/2)&&MAu(f)===Math.floor(m0/2); })());

 ok("S98 Reveal Magic costs 1 ST and tells the caster which enemies within 5 megahexes have secret protection",(()=>{ const [w,f]=pair(); f.stone=true; f.rev=true; const s0=w.hp; const L=castList(w,f).find(x=>x.sp==="Reveal Magic"); dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Reveal Magic"}); const last=G.log.slice(-1)[0]; return !!L&&L.cost===1&&s0-w.hp===1&&/Reverse Missiles and Stone Flesh/.test(last); })());
 ok("S99 a protected enemy more than 5 megahexes away is not reported",(()=>{ let best=0,pr=null; for(const a of P) for(const b of P){ const d=mhDist(a,b); if(d>best){best=d;pr=[a,b];} } if(best<=5) return false; const [w,f]=pair(); w.q=pr[0].q; w.r=pr[0].r; f.q=pr[1].q; f.r=pr[1].r; f.iron=true; dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Reveal Magic"}); return /No secret protection/.test(G.log.slice(-1)[0]); })());
 ok("S100 Reveal Magic marks slippery floors within 5 megahexes for the caster only (the floor is not made public)",(()=>{ const [w,f]=pair(); const g={shown:false}; [{q:f.q,r:f.r}].concat(P.filter(h=>dist(h,f)===1)).forEach(h=>G.objs.push({t:"slick",q:h.q,r:h.r,age:0,g,owner:f})); const before=G.objs.filter(slickVis).length; dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Reveal Magic"}); return before===0&&G.objs.filter(slickVis).length===G.objs.length&&g.shown===false&&/slippery floor/.test(G.log.slice(-1)[0]); })());
 ok("S101 a Spell Shield does not stop Reveal Magic, and a miss costs only 1 ST",(()=>{ const [w,f]=pair(); f.shield=true; dice([3,3,2]); doCast(w,f,{t:"cast",sp:"Reveal Magic"}); const a=/it works \(1 ST\)/.test(G.log.slice(-1)[0])&&w.hp===13; const [w2,f2]=pair(); dice([5,6,5]); doCast(w2,f2,{t:"cast",sp:"Reveal Magic"}); return a&&w2.hp===13; })());

 const garg=(w,f)=>{ const h=creaHexes(w,f,"summon")[0]; const m=summonMinion(w,"gargoyle",h); m.fresh=false; return m; };
 ok("S102 a summoned Gargoyle is a natural flier with MA 8 on the ground and 16 in the air from the first turn; a Wolf is not a flier",(()=>{ const [w,f]=pair(); const m=garg(w,f); const wolf=summonMinion(w,"wolf",creaHexes(w,f,"summon")[1]); const g0=MAu(m); m.air=true; m.airN=0; return m.natFly===true&&!wolf.natFly&&g0===8&&MAu(m)===16; })());
 ok("S103 attacks on a flying Gargoyle are -4, but it has no -2 handicap of its own (unlike a Flight spell)",(()=>{ const [w,f]=pair(); const m=garg(w,f); const g0=adjDXu(m,"single",f), a0=adjDXu(f,"single",m); m.air=true; const g1=adjDXu(m,"single",f), a1=adjDXu(f,"single",m); const fl=pair()[0]; fl.air=true; fl.fly=true; const b=pair()[0]; return g1===g0&&a1===a0-4&&adjDXu(fl,"single",f)===adjDXu(b,"single",f)-2; })());
 ok("S104 a Gargoyle that is four or more hexes from its foe takes to the air and closes in; next to the foe it lands",(()=>{ const [w,f]=pair(); const m=garg(w,f); const far=P.filter(h=>dist(h,f)>=5&&!allU().some(x=>same(x,h)))[0]; m.q=far.q; m.r=far.r; m.f=faceToward(m,f); const d0=dist(m,f); aiMove(m); const up=m.air===true&&dist(m,f)<d0; const nb=[0,1,2,3,4,5].map(d=>nbr(f,d)).find(h=>h&&!allU().some(x=>x.hp>0&&same(x,h))); m.q=nb.q; m.r=nb.r; m.air=true; aiMove(m); return up&&m.air===false; })());
 ok("S105 landing does not cost a natural flier its next move, and a flying Gargoyle can still attack a ground figure beside it",(()=>{ const [w,f]=pair(); const m=garg(w,f); const nb=[0,1,2,3,4,5].map(d=>nbr(f,d)).find(h=>h&&!allU().some(x=>x.hp>0&&same(x,h))); m.q=nb.q; m.r=nb.r; m.f=faceToward(m,f); m.air=true; const att=options(m,f).some(x=>x.t==="attack"); land(m); return att&&m.stop===0&&m.air===false; })());

 ok("S106 the fighter card lists a bow's damage (an archer is not shown as doing no damage), and a bare-handed wizard shows spells",(()=>{ const ar=mkF({name:"Archer",a:"sbow",st:12,dx:14}), wzd=mkF({name:"Wiz",cls:"wizard",st:12,dx:12,iq:12,a:"none",silver:true,spells:["Magic Fist"]}), wst=mkF({name:"Stf",cls:"wizard",st:12,dx:12,iq:12,a:"none",silver:true,spells:["Staff"]}); const c1=card(ar,"foe"), c2=card(wzd,"foe"), c3=card(mkF({name:"Sw",a:"shortsw"}),"foe"); return /Small bow 1d−1 \(missile\)/.test(c1)&&!/<td>none<\/td>/.test(c1.split("Damage")[1].slice(0,60))&&/spells/.test(c2.split("Damage")[1].slice(0,80))&&/Shortsword 2d/i.test(c3)&&/Staff[^<]*1d/.test(card(wst,"foe")); })());
 ok("S107 the warning no longer says missile weapons or hand-to-hand are missing from the arena",(()=>{ const w=warn(mkF({name:"Archer",a:"sbow"})); const w2=warn(mkF({name:"Bare",a:"none",d1:"none"})); return !/Missile weapons are not in/.test(w+w2)&&!/hand-to-hand/.test(w+w2)&&w===""&&/no melee weapon/.test(w2); })());

 return R;
}'''
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(); errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)))
    import os; pg.goto('file://'+os.path.abspath(os.path.join(os.path.dirname(__file__),'..','wizard-arena.html')))
    try:
        R=pg.evaluate(JS)
        for n,ok,x in R: print(('PASS ' if ok else 'FAIL ')+n+(('  ['+x+']') if (x and not ok) else ''))
        print(sum(1 for r in R if r[1]),'/',len(R),'passed')
    except Exception as e: print('ERROR',str(e)[:600])
    print(errs[:3])
